<div class="page-actions"><a class="back-link" href="<?= site_url('admin/modul/'.$slug) ?>">← Daftar tiket</a><?php if (!empty($can_edit) && !in_array($row['status'],array('closed','cancelled'),true)): ?><a class="button button-dark" href="<?= site_url('admin/kasus/'.$slug.'/'.$row['id'].'/ubah') ?>">Ubah tiket</a><?php endif; ?><?php if (!$own): ?><a class="button button-quiet" href="<?= site_url('admin/kasus/'.$slug.'/'.$row['id'].'/berita-acara') ?>" target="_blank">Berita acara draf ↗</a><?php if ($can_cancel && $row['status']==='new'): ?><form method="post" action="<?= site_url('admin/kasus/'.$slug.'/'.$row['id'].'/batalkan') ?>" onsubmit="return confirm('Batalkan tiket baru ini?')"><?= csrf_input() ?><button class="button button-quiet" type="submit">Batalkan tiket</button></form><?php endif; ?><?php endif; ?></div>
<div class="profile-head"><div><span class="panel-overline"><?= h($row['ticket_no']) ?> · <?= h(date('d M Y',strtotime($row['created_at']))) ?></span><h2><?= h($row['title']) ?></h2><p><?= h($row['cooperative_name']?:'Layanan umum') ?> · <?= h($row['assignee_name']?:'Petugas belum ditugaskan') ?></p></div><span class="pill pill-blue"><?= h($statuses[$row['status']]??$row['status']) ?></span></div>
<div class="detail-grid"><section class="panel detail-panel"><span class="panel-overline">URAIAN AWAL</span><p class="case-description"><?= nl2br(h($row['description'])) ?></p></section><section class="panel detail-panel"><span class="panel-overline">PEMOHON</span><dl><dt>Nama</dt><dd><?= h($row['reporter_name']?:'—') ?></dd><?php if (!$own): ?><dt>Kontak</dt><dd><?= h($row['reporter_contact']?:'—') ?></dd><?php endif; ?><dt>Status</dt><dd><?= h($statuses[$row['status']]??$row['status']) ?></dd></dl></section></div>
<?php if ($can_update && $row['status']!=='cancelled'): ?><section class="form-panel case-followup"><div class="form-intro"><span class="panel-overline">TINDAK LANJUT</span><h2>Catat perkembangan</h2></div><form method="post" action="<?= site_url('admin/kasus/'.$slug.'/'.$row['id'].'/tindaklanjut') ?>"><?= csrf_input() ?><div class="form-grid"><label class="form-full">Catatan <span class="required">*</span><textarea name="note" rows="4" minlength="5" required></textarea></label><?php if (!$own): ?><label>Status<select name="status"><?php foreach ($statuses as $code=>$name): if ($code==='cancelled')continue; ?><option value="<?= h($code) ?>" <?= $row['status']===$code?'selected':'' ?>><?= h($name) ?></option><?php endforeach; ?></select></label><label>Akses catatan<select name="visibility"><option value="reporter">Boleh dilihat pemohon</option><option value="internal">Internal petugas</option></select></label><?php endif; ?></div><div class="form-actions"><button class="button button-dark" type="submit">Simpan tindak lanjut →</button></div></form></section><?php endif; ?>
<section class="panel detail-panel case-timeline"><span class="panel-overline">RIWAYAT TIKET</span><?php foreach ($events as $e): ?><article class="timeline-item"><div class="timeline-dot"></div><strong><?= h($e['actor_name']?:'Sistem') ?> <small><?= h(date('d M Y H:i',strtotime($e['created_at']))) ?></small></strong><p><?= nl2br(h($e['note'])) ?></p><?php if (!$own): ?><small><?= $e['visibility']==='internal'?'Internal':'Terlihat pemohon' ?></small><?php endif; ?></article><?php endforeach; ?></section>
